package com.bcsystems.siga.controller;
import com.bcsystems.siga.domain.*; import com.bcsystems.siga.dto.*; import com.bcsystems.siga.service.NominaService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/deduccion-fija") public class DeduccionFijaController {private final NominaService s; public DeduccionFijaController(NominaService s){this.s=s;} @GetMapping @PreAuthorize("hasAuthority('DEDUCCIONES_VER')") public List<DeduccionFija> listar(){return s.listarFijas();} @PostMapping @PreAuthorize("hasAuthority('DEDUCCIONES_CREAR')") public DeduccionFija crear(@RequestBody DeduccionFijaRequest r){return s.crearFija(r);}}
